    func test_setter_dtype_conversion() {
        for (name, x) in layoutVariants(AI){
            x[0] = MfArray([2.7, -2.7, 0.5, -0.5] as [Double])
            XCTAssertClose(x, MfArray([2, -2, 0, 0, 5, 9, -2, 6, 5, 3, 5, 8] as [Int], mftype: .Int, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[0] = MfArray([2.7, -2.7, 0.5, -0.5] as [Double]) \(name)")
        }
        for (name, x) in layoutVariants(U8){
            x[0] = MfArray([300, -1, 256, 255] as [Int])
            XCTAssertClose(x, MfArray([44, 255, 0, 255, 254, 255, 3, 9, 200, 5, 0, 77] as [Int], mftype: .UInt8, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[0] = MfArray([300, -1, 256, 255] as [Int]) \(name)")
        }
        for (name, x) in layoutVariants(U8){
            x[x > 100] = MfArray([300] as [Int])
            XCTAssertClose(x, MfArray([0, 1, 44, 44, 44, 44, 3, 9, 44, 5, 0, 77] as [Int], mftype: .UInt8, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[x > 100] = MfArray([300] as [Int]) \(name)")
        }
        for (name, x) in layoutVariants(U8){
            x[MfArray([2, 0] as [Int], mftype: .Int, shape: [2])] = MfArray([-2] as [Int])
            XCTAssertClose(x, MfArray([254, 254, 254, 254, 254, 255, 3, 9, 254, 254, 254, 254] as [Int], mftype: .UInt8, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[MfArray([2, 0] as [Int], mftype: .Int, shape: [2])] = MfArray([-2] as [Int]) \(name)")
        }
        for (name, x) in layoutVariants(B){
            x[0] = MfArray([0.0, 2.5, -1, 0] as [Double])
            XCTAssertClose(x, MfArray([false, true, true, false, false, true, true, false, true, true, false, false] as [Bool], shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[0] = MfArray([0.0, 2.5, -1, 0] as [Double]) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            x[1, 1~<3] = MfArray([0.1, -1e-3] as [Double])
            XCTAssertClose(x, MfArray([3.0, -1.0, 4.0, 1.0, 5.0, 0.10000000149011612, -0.0010000000474974513, 6.0, 5.0, 3.0, 5.0, 8.0] as [Double], mftype: .Float, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[1, 1~<3] = MfArray([0.1, -1e-3] as [Double]) \(name)")
        }
        for (name, x) in layoutVariants(A){
            x[Matft.all, 0] = MfArray([true, false, true])
            XCTAssertClose(x, MfArray([1.0, -1.0, 4.0, 1.0, 0.0, 9.0, -2.0, 6.0, 1.0, 3.0, 5.0, 8.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[Matft.all, 0] = MfArray([true, false, true]) \(name)")
        }
    }

    func test_bool_setter() {
        for (name, x) in layoutVariants(A){
            x[x > 3] = MfArray([0])
            XCTAssertClose(x, MfArray([3.0, -1.0, 0.0, 1.0, 0.0, 0.0, -2.0, 0.0, 0.0, 3.0, 0.0, 0.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[x > 3] = MfArray([0]) \(name)")
