        for (name, x) in layoutVariants(A){
            x[x > 1000] = MfArray([7])
            XCTAssertClose(x, MfArray([3.0, -1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 8.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[x > 1000] = MfArray([7]) \(name)")
