    func test_fancy_setter() {
        for (name, x) in layoutVariants(A){
            x[MfArray([2, 0] as [Int], mftype: .Int, shape: [2])] = MfArray([-5])
            XCTAssertClose(x, MfArray([-5.0, -5.0, -5.0, -5.0, 5.0, 9.0, -2.0, 6.0, -5.0, -5.0, -5.0, -5.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[MfArray([2, 0] as [Int], mftype: .Int, shape: [2])] = MfArray([-5]) \(name)")
        }
        for (name, x) in layoutVariants(A){
            x[MfArray([-1, 1] as [Int], mftype: .Int, shape: [2])] = MfArray([1, 2, 3, 4, 5, 6, 7, 8] as [Int], mftype: .Int, shape: [2, 4])
            XCTAssertClose(x, MfArray([3.0, -1.0, 4.0, 1.0, 5.0, 6.0, 7.0, 8.0, 1.0, 2.0, 3.0, 4.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[MfArray([-1, 1] as [Int], mftype: .Int, shape: [2])] = MfArray([1, 2, 3, 4, 5, 6, 7, 8] as [Int], mftype: .Int, shape: [2, 4]) \(name)")
        }
        for (name, x) in layoutVariants(A){
            x[MfArray([0, 0] as [Int], mftype: .Int, shape: [2])] = MfArray([1, 2, 3, 4, 5, 6, 7, 8] as [Int], mftype: .Int, shape: [2, 4])
            XCTAssertClose(x, MfArray([5.0, 6.0, 7.0, 8.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 8.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[MfArray([0, 0] as [Int], mftype: .Int, shape: [2])] = MfArray([1, 2, 3, 4, 5, 6, 7, 8] as [Int], mftype: .Int, shape: [2, 4]) \(name)")
        }
        for (name, x) in layoutVariants(A){
            x[MfArray([0, 2] as [Int], mftype: .Int, shape: [2]), MfArray([1, -1] as [Int], mftype: .Int, shape: [2])] = MfArray([100, 200])
            XCTAssertClose(x, MfArray([3.0, 100.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 200.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[MfArray([0, 2] as [Int], mftype: .Int, shape: [2]), MfArray([1, -1] as [Int], mftype: .Int, shape: [2])] = MfArray([100, 200]) \(name)")
        }
        for (name, x) in layoutVariants(A){
            x[MfArray([0, 2] as [Int], mftype: .Int, shape: [2, 1]), MfArray([1, 3] as [Int], mftype: .Int, shape: [2])] = MfArray([9])
            XCTAssertClose(x, MfArray([3.0, 9.0, 4.0, 9.0, 5.0, 9.0, -2.0, 6.0, 5.0, 9.0, 5.0, 9.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[MfArray([0, 2] as [Int], mftype: .Int, shape: [2, 1]), MfArray([1, 3] as [Int], mftype: .Int, shape: [2])] = MfArray([9]) \(name)")
        }
        for (name, x) in layoutVariants(A){
            x[MfArray([] as [Int], mftype: .Int, shape: [0])] = MfArray([9])
            XCTAssertClose(x, MfArray([3.0, -1.0, 4.0, 1.0, 5.0, 9.0, -2.0, 6.0, 5.0, 3.0, 5.0, 8.0] as [Double], mftype: .Double, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[MfArray([] as [Int], mftype: .Int, shape: [0])] = MfArray([9]) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            x[MfArray([2, 0] as [Int], mftype: .Int, shape: [2])] = MfArray([-5])
            XCTAssertClose(x, MfArray([-5.0, -5.0, -5.0, -5.0, 5.0, 9.0, -2.0, 6.0, -5.0, -5.0, -5.0, -5.0] as [Double], mftype: .Float, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[MfArray([2, 0] as [Int], mftype: .Int, shape: [2])] = MfArray([-5]) \(name)")
        }
