            XCTAssertClose(x, MfArray([3.0, -1.0, 4.0, 1.0, 5.0, 6.0, 7.0, 8.0, 1.0, 2.0, 3.0, 4.0] as [Double], mftype: .Float, shape: [3, 4]), rtol: 0, atol: 0, checkType: true, "x[MfArray([-1, 1] as [Int], mftype: .Int, shape: [2])] = MfArray([1, 2, 3, 4, 5, 6, 7, 8] as [Int], mftype: .Int, shape: [2, 4]) \(name)")
        }
        for (name, x) in layoutVariants(AF){
            x[MfArray([0, 0] as [Int], mftype: .Int, shape: [2])] = MfArray([1, 2, 3, 4, 5, 6, 7, 8] as [Int], mftype: .Int, shape: [2, 4])
