            let r = base[1~<4]
            r[Matft.all, 1~<3] = r[Matft.all, 0~<2]
            XCTAssertClose(base, MfArray([0.0, 1.0, 2.0, 3.0, 4.0, 4.0, 5.0, 7.0, 8.0, 8.0, 9.0, 11.0, 12.0, 12.0, 13.0, 15.0, 16.0, 17.0, 18.0, 19.0] as [Double], mftype: .Double, shape: [5, 4]), rtol: 0, atol: 0, checkType: true, "let r = base[1~<4] ; r[Matft.all, 1~<3] = r[Matft.all, 0~<2]")
        }
        do {
